{
  "name": "Robotell CAN总线接口",
  "name_en": "Robotell CAN Bus Interface",
  "manufacturer": "Robotell",
  "description": "用于连接和配置 Robotell CAN 总线接口设备的通信接口，可设置 CAN 比特率、串口速率、自动重传和硬件过滤，并发送 CAN 帧。适合在实验系统中与使用 CAN 总线通信的控制器、传感器或执行机构进行数据交换。",
  "description_en": "A communication interface for connecting to and configuring a Robotell CAN bus interface device. It supports setting CAN bitrate, serial port rate, automatic retransmission, and hardware filters, and can transmit CAN frames. It is suitable for laboratory systems that need to exchange data with CAN-based controllers, sensors, or actuators.",
  "actions": [
    {
      "action_name": "auto-set_bitrate",
      "description": "设置 CAN 总线比特率。",
      "description_en": "Set the CAN bus bitrate."
    },
    {
      "action_name": "auto-set_auto_retransmit",
      "description": "设置是否自动重传未确认的 CAN 帧。",
      "description_en": "Enable or disable automatic retransmission of unacknowledged CAN frames."
    },
    {
      "action_name": "auto-set_auto_bus_management",
      "description": "设置是否启用自动总线管理。",
      "description_en": "Enable or disable automatic bus management."
    },
    {
      "action_name": "auto-set_serial_rate",
      "description": "设置串口接口波特率。",
      "description_en": "Set the serial interface baud rate."
    },
    {
      "action_name": "auto-set_hw_filter",
      "description": "配置硬件消息过滤器。",
      "description_en": "Configure a hardware message filter."
    },
    {
      "action_name": "auto-flush",
      "description": "清空接口缓冲区。",
      "description_en": "Flush the interface buffers."
    },
    {
      "action_name": "auto-send",
      "description": "发送 CAN 消息帧。",
      "description_en": "Send a CAN message frame."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭总线接口连接。",
      "description_en": "Shut down the bus interface connection."
    },
    {
      "action_name": "auto-fileno",
      "description": "获取接口对应的文件描述符。",
      "description_en": "Get the file descriptor associated with the interface."
    },
    {
      "action_name": "auto-get_serial_number",
      "description": "获取该 slcan 接口的序列号。",
      "description_en": "Get the serial number of the slcan interface."
    }
  ],
  "tag_hints": [
    "CAN bus communication",
    "serial-to-CAN interface",
    "bitrate configuration",
    "hardware CAN filtering",
    "CAN frame transmission",
    "slcan interface",
    "bus adapter"
  ]
}

